$capture=@($wrapper.PSObject.Properties|Where-Object{$_.Name -match '"'CaptureComplete"'$'"'});if("'$capture.Count -ne 2 -or @($capture|Where-Object{$_.Value -ne $true}).Count){throw '"'CAPTURE'}
